scripts:
await page.goto('https://github.com/rust-lang/rust');
await page.getByRole('heading', {name: /The Rust Programming Language/i}).first().count();
return await page.evaluate(() => cu.claim({key_text: 'rust-lang/rust', answer: location.href}));

await page.goto('https://en.wikipedia.org/wiki/Eiffel_Tower');
return await page.evaluate(() => {
  const text = document.body.innerText;
  const key_text = 'in Paris, France';
  const match = text.match(/in (Paris), France/);
  return cu.claim({key_text, answer: match ? match[1] : ''});
});

await page.goto('https://www.selenium.dev/selenium/web/web-form.html');
await cu.click('Submit');
await page.evaluate(() => cu.claim({key_text: 'Received!', answer: document.querySelector('h1')?.innerText?.trim()}));

await page.goto('https://the-internet.herokuapp.com/login');
const text = await page.locator('body').innerText();
const username = text.match(/username\s+([\w.-]+)/i)?.[1];
const password = text.match(/password\s+([\w.-]+)/i)?.[1];
if (username) await cu.fill('Username', username);
if (password) await cu.fill('Password', password);
await cu.click('Login');
await page.evaluate(() => cu.claim({key_text: document.querySelector('#flash')?.innerText || document.body.innerText, answer: document.querySelector('#flash')?.innerText?.trim()}));

await page.goto('https://the-internet.herokuapp.com/login');
const credentials = await page.evaluate(() => document.body.innerText);
const username = credentials.match(/username\s+([\w.-]+)/i)?.[1];
const password = credentials.match(/password\s+([\w.-]+)/i)?.[1];
if (username) await cu.fill('Username', username);
if (password) await cu.fill('Password', password);
await cu.click('Login');
await page.evaluate(() => cu.claim({key_text: document.querySelector('#flash')?.innerText.trim(), answer: document.querySelector('#flash')?.innerText.trim()}));

await page.goto('https://testpages.herokuapp.com/styled/basic-html-form-test.html');
await cu.fill('Username', 'demo');
await cu.fill('Password', 'secret');
await cu.fill('Comments', 'hello');
await cu.click('Submit');
await page.evaluate(() => cu.claim({key_text: 'Comments', answer: cu.text('Comments')}));

await page.goto('https://httpbin.org/forms/post');
await cu.click('Submit');
await page.evaluate(() => {
  const body = document.body.innerText;
  let answer = '';
  try {
    const data = JSON.parse(body);
    const form = data.form || {};
    answer = Object.keys(form).find(k => /tel|phone/i.test(k)) || '';
  } catch {}
  return cu.claim({key_text: 'Your phone', answer});
});

await page.goto('https://httpbin.org/forms/post');
await cu.click('Submit');
await page.evaluate(() => {
  const data = JSON.parse(document.body.innerText);
  const answer = Object.keys(data.form).find(name => /tel|phone/i.test(name));
  return cu.claim({key_text: answer, answer});
});

await page.goto('https://www.npmjs.com/');
await cu.search('jest');
await cu.click('jest');
return await page.evaluate(() => cu.claim({key_text: 'jest', answer: document.querySelector('h1')?.innerText?.trim()}));

await page.goto('https://github.blog/page/2/');
return await page.evaluate(() => {
  const h1 = document.querySelector('h1')?.innerText?.trim() || document.title;
  const phrase = document.body.innerText.split('\n').map(s => s.trim()).find(s => s && s.length > 5) || h1;
  return cu.claim({key_text: phrase, answer: window.location.href});
});

await page.goto('https://github.blog/');
await cu.click('2');
return await page.evaluate(() => cu.claim({key_text: 'Latest', answer: window.location.href}));

await page.goto('https://stackoverflow.blog/page/2/');
await page.evaluate(() => {
  const phrase = document.querySelector('h1')?.innerText || document.title;
  return cu.claim({key_text: phrase, answer: location.href});
});

await page.goto('https://make.wordpress.org/core/');
await cu.click('Older posts');
await page.evaluate(() => cu.claim({key_text: 'Older posts', answer: location.href}));

await page.goto('https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml');
await cu.search('https');
return await page.evaluate(() => {
  const row = [...document.querySelectorAll('tr')].find(r => {
    const cells = [...r.querySelectorAll('th, td')].map(c => c.innerText.trim());
    return cells.length >= 2 && cells[0].toLowerCase() === 'https';
  });
  const cells = row ? [...row.querySelectorAll('th, td')].map(c => c.innerText.trim()) : [];
  return cu.claim({key_text: row ? row.innerText.trim() : 'https', answer: cells[1] || ''});
});

await page.goto('https://en.wikipedia.org/wiki/List_of_HTTP_status_codes');
await page.evaluate(() => {
  const h = [...document.querySelectorAll('h3,h4')].find(el => /2xx success/.test(el.innerText));
  const section = h?.parentElement?.parentElement;
  const text = (section?.innerText || document.querySelector('#mw-content-text')?.innerText || '');
  const match = text.match(/201\s+([^\n]+)/);
  return cu.claim({key_text: match ? `201 ${match[1].trim()}` : '2xx success', answer: match ? match[1].trim() : ''});
});

await page.goto('https://en.wikipedia.org/wiki/List_of_country_calling_codes');
await page.getByText('Japan', { exact: true }).first();
await page.evaluate(() => cu.claim({key_text: 'Japan', answer: cu.text('Japan')}));

await page.goto('https://en.wikipedia.org/wiki/HTML_element');
return await page.evaluate(() => {
  const rows = [...document.querySelectorAll('table tr')];
  let found = rows.find(r => /row of cells|row.*table|table row/i.test(r.innerText));
  let answer = '';
  let key_text = '';
  if (found) {
    const text = found.innerText;
    key_text = text.match(/.{0,80}(?:row of cells|row.*table|table row).{0,100}/i)?.[0] || text;
    const code = [...found.querySelectorAll('code, a, span')].map(x => x.innerText.trim()).find(x => /^<tr\s*\/?>$|^tr$/i.test(x));
    answer = code || (text.match(/<tr\s*\/?>/i)?.[0]) || '';
  }
  if (!answer) {
    const body = document.body.innerText;
    const m = body.match(/<tr\s*\/?>/i);
    answer = m?.[0] || '';
    key_text = body.match(/.{0,90}(?:row of cells|table row|row in a table).{0,100}/i)?.[0] || 'HTML elements';
  }
  return cu.claim({key_text, answer});
});

await page.goto('https://en.wikipedia.org/wiki/HTML_element');
return await page.evaluate(() => {
  const body = document.body.innerText;
  const key_text = body.match(/Contains a row of cells in a <table>\./)?.[0] || 'Contains a row of cells in a <table>.';
  const answer = body.match(/<tr\s*\/?>/i)?.[0] || 'tr';
  return cu.claim({key_text, answer});
});

await page.goto('https://www.unicode.org/charts/');
await cu.click('Currency Symbols');
await page.evaluate(() => cu.claim({key_text: 'EURO SIGN', answer: document.body.innerText.match(/20AC[^
]*
\s*([^
]+)/)?.[1]?.trim() || 'EURO SIGN'}));

await page.goto('https://redis.io/commands/get/');
await page.evaluate(() => {
  const h1 = document.querySelector('h1')?.innerText?.trim() || '';
  return cu.claim({key_text: 'GET', answer: h1});
});
